"""The kitty data model: members, expenses, payments and the maths on top.

Money is stored in kitty.json as two-decimal strings. Foreign-currency
expenses and payments are converted to the base currency when they are
recorded, using the rate in effect at that moment, and the converted amount is
stored alongside the original. Changing a rate later only affects new entries.
"""

import json
import os
import re
import tempfile
from datetime import date, datetime
from decimal import Decimal

from kitty.errors import KittyError
from kitty.money import (
    allocate,
    convert,
    fmt,
    parse_amount,
    parse_currency,
    parse_positive_number,
    to_cents,
)

FILENAME = "kitty.json"
DEFAULT_CATEGORY = "other"
_DATE_RE = re.compile(r"^\d{4}-\d{2}-\d{2}$")


def parse_date(text):
    if text is None:
        return date.today().isoformat()
    text = text.strip()
    try:
        if not _DATE_RE.match(text):
            raise ValueError
        datetime.strptime(text, "%Y-%m-%d")
    except ValueError:
        raise KittyError(f"invalid date {text!r}: expected YYYY-MM-DD") from None
    return text


def _parse_pairs(text, option):
    """Parse 'A=30,B=20' into [('A', '30'), ('B', '20')]."""
    pairs = []
    for item in text.split(","):
        name, sep, value = item.partition("=")
        name, value = name.strip(), value.strip()
        if not sep or not name or not value:
            raise KittyError(f"invalid {option} entry {item.strip()!r}: expected NAME=VALUE")
        pairs.append((name, value))
    return pairs


class Kitty:
    def __init__(self, data, path):
        self.data = data
        self.path = path

    # ----- storage -----

    @classmethod
    def create(cls, base_currency, directory="."):
        path = os.path.join(directory, FILENAME)
        if os.path.exists(path):
            raise KittyError(f"{FILENAME} already exists here; refusing to overwrite it")
        data = {
            "version": 1,
            "base_currency": parse_currency(base_currency),
            "members": [],
            "rates": {},
            "expenses": [],
            "payments": [],
            "next_expense_id": 1,
            "next_seq": 1,
        }
        kitty = cls(data, path)
        kitty.save()
        return kitty

    @classmethod
    def load(cls, directory="."):
        path = os.path.join(directory, FILENAME)
        try:
            with open(path, encoding="utf-8") as f:
                data = json.load(f)
        except FileNotFoundError:
            raise KittyError(f"no {FILENAME} here; run 'init CURRENCY' first") from None
        except (OSError, ValueError) as e:
            raise KittyError(f"could not read {FILENAME}: {e}") from None
        required = {"base_currency", "members", "rates", "expenses", "payments",
                    "next_expense_id", "next_seq"}
        if not isinstance(data, dict) or not required <= data.keys():
            raise KittyError(f"{FILENAME} is not a valid kitty file")
        return cls(data, path)

    def save(self):
        # Write to a temporary file and rename it over the original, so an
        # interrupted write can never leave a half-written kitty.json behind.
        directory = os.path.dirname(os.path.abspath(self.path))
        try:
            fd, tmp = tempfile.mkstemp(dir=directory, prefix=".kitty-", suffix=".json")
            with os.fdopen(fd, "w", encoding="utf-8") as f:
                json.dump(self.data, f, indent=2, ensure_ascii=False)
                f.write("\n")
            os.replace(tmp, self.path)
        except OSError as e:
            raise KittyError(f"could not write {FILENAME}: {e}") from None

    # ----- helpers -----

    @property
    def base(self):
        return self.data["base_currency"]

    @property
    def members(self):
        return self.data["members"]

    def _require_member(self, name):
        if name not in self.members:
            raise KittyError(f"unknown member {name!r}")

    def _next_seq(self):
        seq = self.data["next_seq"]
        self.data["next_seq"] = seq + 1
        return seq

    def _to_base(self, cents, currency):
        if currency == self.base:
            return cents
        rate = self.data["rates"].get(currency)
        if rate is None:
            raise KittyError(
                f"no exchange rate for {currency}; set one with 'rate set {currency} RATE'"
            )
        return convert(cents, Decimal(rate))

    def _referenced(self, name):
        for e in self.data["expenses"]:
            if e["payer"] == name or name in e["shares"]:
                return True
        return any(p["from"] == name or p["to"] == name for p in self.data["payments"])

    # ----- members -----

    def add_member(self, name):
        name = name.strip()
        if not name:
            raise KittyError("member name cannot be empty")
        if any(c in name for c in ",="):
            raise KittyError(f"invalid member name {name!r}: cannot contain ',' or '='")
        for existing in self.members:
            if existing.lower() == name.lower():
                raise KittyError(f"member {existing!r} already exists")
        self.members.append(name)

    def remove_member(self, name):
        self._require_member(name)
        if self._referenced(name):
            raise KittyError(
                f"cannot remove {name!r}: they appear in recorded expenses or payments"
            )
        self.members.remove(name)

    # ----- rates -----

    def set_rate(self, currency, rate):
        currency = parse_currency(currency)
        if currency == self.base:
            raise KittyError(f"{currency} is the base currency; its rate is always 1")
        self.data["rates"][currency] = str(parse_positive_number(rate, "rate"))

    # ----- expenses -----

    def add_expense(self, payer, amount, description, among=None, exact=None,
                    shares=None, percent=None, currency=None, when=None, category=None):
        self._require_member(payer)
        description = description.strip()
        if not description:
            raise KittyError("description cannot be empty")
        cents = parse_amount(amount)
        currency = parse_currency(currency) if currency else self.base
        when = parse_date(when)
        category = (category or DEFAULT_CATEGORY).strip().lower()
        if not category:
            raise KittyError("category cannot be empty")

        given = [o for o, v in (("--among", among), ("--exact", exact),
                                ("--shares", shares), ("--percent", percent)) if v is not None]
        if len(given) > 1:
            raise KittyError(f"use only one of {', '.join(given)}")

        if exact is not None:
            pairs = [(n, parse_amount(v, f"exact amount for {n}"))
                     for n, v in _parse_pairs(exact, "--exact")]
            total = sum(v for _, v in pairs)
            if total != cents:
                raise KittyError(
                    f"--exact amounts add up to {fmt(total)} but the expense is {fmt(cents)}"
                )
            weights = [(n, Decimal(v)) for n, v in pairs]
        elif shares is not None:
            weights = [(n, parse_positive_number(v, f"share for {n}"))
                       for n, v in _parse_pairs(shares, "--shares")]
        elif percent is not None:
            weights = [(n, parse_positive_number(v, f"percent for {n}"))
                       for n, v in _parse_pairs(percent, "--percent")]
            total = sum(w for _, w in weights)
            if total != 100:
                raise KittyError(f"--percent values add up to {total}, not 100")
        else:
            if among is not None:
                names = [n.strip() for n in among.split(",")]
                if any(not n for n in names):
                    raise KittyError(f"invalid --among list {among!r}")
            else:
                names = list(self.members)
            weights = [(n, Decimal(1)) for n in names]

        if not weights:
            raise KittyError("nobody to split the expense among; add members first")
        seen = set()
        for name, _ in weights:
            self._require_member(name)
            if name in seen:
                raise KittyError(f"{name!r} is listed more than once")
            seen.add(name)

        base_cents = self._to_base(cents, currency)
        split = allocate(base_cents, weights)
        expense = {
            "id": self.data["next_expense_id"],
            "seq": self._next_seq(),
            "date": when,
            "payer": payer,
            "description": description,
            "amount": fmt(cents),
            "currency": currency,
            "base_amount": fmt(base_cents),
            "category": category,
            "shares": {n: fmt(c) for n, c in split.items()},
        }
        self.data["next_expense_id"] += 1
        self.data["expenses"].append(expense)
        return expense["id"]

    def remove_expense(self, expense_id):
        try:
            wanted = int(expense_id)
        except ValueError:
            raise KittyError(f"invalid expense ID {expense_id!r}") from None
        for i, e in enumerate(self.data["expenses"]):
            if e["id"] == wanted:
                del self.data["expenses"][i]
                return
        raise KittyError(f"no expense with ID {wanted}")

    def list_expenses(self):
        return [
            {k: e[k] for k in ("id", "date", "payer", "description", "amount", "currency",
                               "base_amount", "category", "shares")}
            for e in sorted(self.data["expenses"], key=lambda e: e["id"])
        ]

    # ----- payments -----

    def add_payment(self, sender, recipient, amount, currency=None, when=None):
        self._require_member(sender)
        self._require_member(recipient)
        if sender == recipient:
            raise KittyError("a payment needs two different people")
        cents = parse_amount(amount)
        currency = parse_currency(currency) if currency else self.base
        when = parse_date(when)
        self.data["payments"].append({
            "seq": self._next_seq(),
            "date": when,
            "from": sender,
            "to": recipient,
            "amount": fmt(cents),
            "currency": currency,
            "base_amount": fmt(self._to_base(cents, currency)),
        })

    # ----- reports -----

    def _events(self):
        """Every (date, seq, description, {member: change in cents}, payment or None),
        in date order, ties broken by the order they were recorded."""
        events = []
        for e in self.data["expenses"]:
            changes = {n: -to_cents(s) for n, s in e["shares"].items()}
            changes[e["payer"]] = changes.get(e["payer"], 0) + to_cents(e["base_amount"])
            events.append((e["date"], e["seq"], e["description"], changes, None))
        for p in self.data["payments"]:
            cents = to_cents(p["base_amount"])
            events.append((p["date"], p["seq"], None, {p["from"]: cents, p["to"]: -cents}, p))
        events.sort(key=lambda ev: (ev[0], ev[1]))
        return events

    def balance_cents(self):
        balances = {n: 0 for n in self.members}
        for _, _, _, changes, _ in self._events():
            for name, cents in changes.items():
                balances[name] = balances.get(name, 0) + cents
        return balances

    def balances(self):
        return {n: fmt(c) for n, c in self.balance_cents().items()}

    def settle(self):
        """Greedy settlement: the biggest debtor pays the biggest creditor, repeat.

        Produces at most (number of members - 1) payments.
        """
        balances = self.balance_cents()
        order = {n: i for i, n in enumerate(balances)}
        creditors = [[c, n] for n, c in balances.items() if c > 0]
        debtors = [[-c, n] for n, c in balances.items() if c < 0]
        transfers = []
        while creditors and debtors:
            creditors.sort(key=lambda x: (-x[0], order[x[1]]))
            debtors.sort(key=lambda x: (-x[0], order[x[1]]))
            credit, debt = creditors[0], debtors[0]
            amount = min(credit[0], debt[0])
            transfers.append({"from": debt[1], "to": credit[1], "amount": fmt(amount)})
            credit[0] -= amount
            debt[0] -= amount
            creditors = [c for c in creditors if c[0] > 0]
            debtors = [d for d in debtors if d[0] > 0]
        return transfers

    def history(self, name):
        self._require_member(name)
        rows = []
        balance = 0
        for when, _, description, changes, payment in self._events():
            if name not in changes:
                continue
            if payment is not None:
                if payment["from"] == name:
                    description = f"Payment to {payment['to']}"
                else:
                    description = f"Payment from {payment['from']}"
            balance += changes[name]
            rows.append({"date": when, "description": description,
                         "change": fmt(changes[name]), "balance": fmt(balance)})
        return rows

    def report(self):
        totals = {}
        for e in self.data["expenses"]:
            per_member = totals.setdefault(e["category"], {})
            for name, share in e["shares"].items():
                per_member[name] = per_member.get(name, 0) + to_cents(share)
        order = {n: i for i, n in enumerate(self.members)}
        return {
            category: {n: fmt(c) for n, c in sorted(per_member.items(),
                                                     key=lambda kv: order.get(kv[0], 0))}
            for category, per_member in sorted(totals.items())
        }

    def export_rows(self):
        return [
            {k: e[k] for k in ("id", "date", "payer", "description", "amount", "currency",
                               "category", "base_amount")}
            for e in sorted(self.data["expenses"], key=lambda e: e["id"])
        ]
